import type { Readable } from 'node:stream';

/**
 * Where file bytes live. Controllers and business services never see one of
 * these: they go through FilesService, which goes through StorageService.
 * Swapping local disk for S3 (or S3 for something else) is a new class here.
 *
 * Keys are generated by the server and checked by `assertSafeKey` at this
 * boundary as well, so a bad key cannot reach a filesystem or a bucket even
 * if some caller forgot.
 */
export type StorageProviderName = 'local' | 's3';

export interface StoredObject {
  body: Readable;
  contentLength: number | null;
}

export interface StorageProvider {
  readonly name: StorageProviderName;
  /** Stream the body in; never buffers the whole object. */
  put(
    key: string,
    body: Readable,
    info: { contentType: string; contentLength: number },
  ): Promise<void>;
  /** @throws StorageObjectMissingError when there is no such object. */
  get(key: string): Promise<StoredObject>;
  /** Removing an object that is already gone succeeds. */
  delete(key: string): Promise<void>;
  /** A short-lived URL that downloads exactly this object. */
  signedUrl(
    key: string,
    options: { expiresInSeconds: number; contentType: string; fileName: string },
  ): Promise<string>;
}

export class StorageObjectMissingError extends Error {
  constructor() {
    super('No such object.');
    this.name = 'StorageObjectMissingError';
  }
}

/** The backend failed. Its message is for logs, never for the client. */
export class StorageBackendError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'StorageBackendError';
  }
}

/** `public/<company uuid>/<purpose>/<uuid>.<ext>` — nothing else is a key. */
const SAFE_KEY = /^(public|private)\/[0-9a-f-]{36}\/[a-z_]+\/[0-9a-f-]{36}\.[a-z0-9]{2,5}$/;

export function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key)) throw new StorageBackendError('Refusing an unsafe storage key.');
}

/** `Content-Disposition` with a name that cannot break the header. */
export function contentDisposition(
  fileName: string,
  disposition: 'inline' | 'attachment' = 'inline',
): string {
  const ascii =
    fileName
      .replace(/[^\x20-\x7e]/g, '_')
      .replace(/["\\]/g, '_')
      .slice(0, 120) || 'file';
  return `${disposition}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(fileName.slice(0, 120))}`;
}
